export const setCellSelection =
	(type: 'col' | 'row') =>
	({ state, dispatch }: EditorView, pos: number) => {
		const $cell = cellAround(state.doc.resolve(pos));
		if ($cell) {
			const sel =
				type === 'row'
					? CellSelection.rowSelection($cell)
					: CellSelection.colSelection($cell);
			dispatch(state.tr.setSelection(sel));
		}
	};

export const createTable: (rows: number, columns: number) => Command =
	(rows, columns) => (state, dispatch, view) => {
		const { table, tableRow, tableHeader, tableCell, paragraph } =
			state.schema.nodes;
		const cols = Array(columns).fill({ width: cellMinWidth });
		const tableNode = createNode(
			table,
			{ cols },
			Array(rows)
				.fill(null)
				.map((_, row) =>
					createNode(
						tableRow,
						null,
						Array(columns)
							.fill(null)
							.map((_, col) =>
								createNode(
									// row === 0 ? tableHeader : tableCell,
									tableCell,
									null,
									createNode(
										paragraph,
										null
										// state.schema.text('cell row ' + row + ', col ' + col)
									)
								)
							)
					)
				)
		);
		TableMap.get(tableNode);
		if (dispatch) {
			dispatch(state.tr.replaceSelectionWith(tableNode).scrollIntoView());
			return true;
		}

		return false;
	};

export function insertTable(
	state: EditorState,
	dispatch: EditorView['dispatch']
) {
	const { schema } = state;
	const table = schema.nodes.table;
	const row = schema.nodes.table_row;
	const cell = schema.nodes.table_cell;
	const paragraph = schema.nodes.paragraph;
	const tableNode = createNode(
		table,
		{ cols: Array(3).fill({ width: cellMinWidth }) },
		Array(3)
			.fill(null)
			.map((_, r) =>
				createNode(
					row,
					null,
					Array(3)
						.fill(null)
						.map((_, col) =>
							createNode(
								cell,
								null,
								createNode(
									paragraph,
									null,
									schema.text(`hello row ${r + 1} col ${col + 1}`)
								)
							)
						)
				)
			)
	);
	dispatch(state.tr.replaceSelectionWith(tableNode).scrollIntoView());
}

export interface TableCtx {
	tableStart: number;
	map: TableMap;
	table: Node;
}
export type TableRect = Rect & TableCtx;

export function selectedRect(state: EditorState): TableRect {
	const sel = state.selection;
	const $pos = selectionCell(state);
	const table = $pos.node(-1);
	const tableStart = $pos.start(-1);
	const map = TableMap.get(table);

	const rect =
		sel instanceof CellSelection
			? map.rectBetween(
					sel.$anchorCell.pos - tableStart,
					sel.$headCell.pos - tableStart
				)
			: map.findCell($pos.pos - tableStart);

	return { ...rect, tableStart, map, table };
}

export function addColumn(
	tr: Transaction,
	{ map, table, tableStart }: TableCtx,
	col: number
) {
	let refColumn: number | null = col > 0 ? -1 : 0;
	if (columnIsHeader(map, table, col + refColumn)) {
		refColumn = col == 0 || col == map.width ? null : 0;
	}

	for (let row = 0; row < map.height; row++) {
		const index = row * map.width + col;
		if (col > 0 && col < map.width && map.map[index - 1] == map.map[index]) {
			const pos = map.map[index];
			const cell = table.nodeAt(pos)!;
			tr.setNodeMarkup(
				tr.mapping.map(tableStart + pos),
				null,
				addColspan(cell.attrs as CellAttrs, col - map.colCount(pos))
			);
			row += cell.attrs.rowspan - 1;
		} else {
			const type =
				refColumn == null
					? tableNodeTypes(table.type.schema).cell
					: table.nodeAt(map.map[index + refColumn])!.type;
			const pos = map.positionAt(row, col, table);

			tr.insert(tr.mapping.map(tableStart + pos), createNodeAndFill(type)!);
		}
	}
	const cols = table.attrs.cols.concat();
	cols.splice(col, 0, { width: cellMinWidth });
	tr.setNodeAttribute(tableStart - 1, 'cols', cols);
	return tr;
}

export const addColumnBefore: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	if (dispatch) {
		const rect = selectedRect(state);
		dispatch(addColumn(state.tr, rect, rect.left));
	}
	return true;
};

export const addColumnAfter: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	if (dispatch) {
		const rect = selectedRect(state);
		dispatch(addColumn(state.tr, rect, rect.right));
	}
	return true;
};

export const addColumnAtEnd = (pos: number, view: EditorView) => {
	const { state, dispatch } = view;
	let tr = state.tr;
	const tableStart = tr.mapping.map(pos);
	const $start = state.doc.resolve(tableStart);
	const table = $start.nodeAfter!;

	const map = TableMap.get(table);
	dispatch(addColumn(tr, { map, table, tableStart: pos + 1 }, map.width));
};

export const removeColumn = (
	tr: Transaction,
	{ map, table, tableStart }: TableCtx,
	col: number
): Transaction => {
	const mapStart = tr.mapping.maps.length;

	for (let row = 0; row < map.height; ) {
		const index = row * map.width + col;
		const pos = map.map[index];
		const cell = table.nodeAt(pos)!;
		const attrs = cell.attrs as CellAttrs;

		if (
			(col > 0 && map.map[index - 1] == pos) ||
			(col < map.width - 1 && map.map[index + 1] == pos)
		) {
			tr.setNodeMarkup(
				tr.mapping.slice(mapStart).map(tableStart + pos),
				null,
				removeColSpan(attrs, col - map.colCount(pos))
			);
		} else {
			const start = tr.mapping.slice(mapStart).map(tableStart + pos);
			tr.delete(start, start + cell.nodeSize);
		}
		row += attrs.rowspan;
	}
	const cols = table.attrs.cols.concat();
	cols.splice(col, 1);
	tr.setNodeAttribute(tableStart - 1, 'cols', cols);
	return tr;
};

export const deleteColumn: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	if (dispatch) {
		const rect = selectedRect(state);
		let tr = state.tr;

		if (rect.left == 0 && rect.right == rect.map.width) return false;

		const $pos = selectionCell(state);

		for (let i = rect.right - 1; ; i--) {
			removeColumn(tr, rect, i);
			if (i == rect.left) break;
			const table = rect.tableStart
				? tr.doc.nodeAt(rect.tableStart - 1)
				: tr.doc;
			if (!table) throw new RangeError('No table found');
			rect.table = table;
			rect.map = TableMap.get(table);
		}

		tr.setSelection(TextSelection.create(tr.doc, tr.mapping.map($pos.pos)));
		dispatch(tr);
	}
	return true;
};

export const deleteColumnAtEnd = (view: EditorView, pos: number) => {
	const $pos = view.state.doc.resolve(pos);
	const table = $pos.nodeAfter!;
	const map = TableMap.get(table);
	if (map.width <= 1) return;
	const tr = removeColumn(
		view.state.tr,
		{ map, table, tableStart: pos + 1 },
		map.width - 1
	);
	view.dispatch(tr);
};

export const rowIsHeader = (
	map: TableMap,
	table: Node,
	row: number
): boolean => {
	const headerCell = tableNodeTypes(table.type.schema).headerCell;
	for (let col = 0; col < map.width; col++)
		if (table.nodeAt(map.map[col + row * map.width])?.type != headerCell)
			return false;

	return true;
};

export const addRow = (
	tr: Transaction,
	{ map, table, tableStart }: TableCtx,
	row: number
): Transaction => {
	let rowPos = tableStart;
	for (let i = 0; i < row; i++) rowPos += table.child(i).nodeSize;
	const cells = [];
	let refRow: number | null = row > 0 ? -1 : 0;

	if (rowIsHeader(map, table, row + refRow))
		refRow = row == 0 || row == map.height ? null : 0;

	for (let col = 0, index = map.width * row; col < map.width; col++, index++) {
		if (
			row > 0 &&
			row < map.height &&
			map.map[index] == map.map[index - map.width]
		) {
			const pos = map.map[index];
			const attrs = table.nodeAt(pos)!.attrs;
			tr.setNodeMarkup(tableStart + pos, null, {
				...attrs,
				rowspan: attrs.rowspan + 1
			});
			col += attrs.colspan - 1;
		} else {
			const type =
				refRow === null
					? tableNodeTypes(table.type.schema).cell
					: table.nodeAt(map.map[index + refRow * map.width])?.type;
			const node = type ? createNodeAndFill(type) : void 0;
			if (node) cells.push(node);
		}
	}
	tr.insert(
		rowPos,
		createNode(tableNodeTypes(table.type.schema).row, null, cells)
	);
	return tr;
};

export const addRowBefore: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	if (dispatch) {
		const rect = selectedRect(state);
		const tr = addRow(state.tr, rect, rect.top);
		dispatch(tr);
	}
	return true;
};

export const addRowAfter: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	if (dispatch) {
		const rect = selectedRect(state);
		const tr = addRow(state.tr, rect, rect.bottom);
		dispatch(tr);
	}
	return true;
};

export const addRowAtEnd = (pos: number, view: EditorView) => {
	const $pos = view.state.doc.resolve(pos);
	const table = $pos.nodeAfter!;
	const map = TableMap.get(table);
	view.dispatch(
		addRow(view.state.tr, { map, table, tableStart: pos + 1 }, map.height)
	);
};

export const removeRow = (
	tr: Transaction,
	{ map, table, tableStart }: TableCtx,
	row: number
) => {
	let rowPos = 0;
	for (let i = 0; i < row; i++) rowPos += table.child(i).nodeSize;
	const nextRow = rowPos + table.child(row).nodeSize;
	const mapFrom = tr.mapping.maps.length;

	tr.delete(rowPos + tableStart, nextRow + tableStart);

	const seen = new Set<number>();

	for (let col = 0, index = row * map.width; col < map.width; col++, index++) {
		const pos = map.map[index];

		if (seen.has(pos)) continue;

		seen.add(pos);
		if (row > 0 && pos == map.map[index - map.width]) {
			const attrs = table.nodeAt(pos)?.attrs as CellAttrs;
			tr.setNodeMarkup(tr.mapping.slice(mapFrom).map(pos + tableStart), null, {
				...attrs,
				rowspan: attrs.rowspan - 1
			});
			col += attrs.colspan - 1;
		} else if (row < map.height && pos == map.map[index + map.width]) {
			const cell = table.nodeAt(pos)!;
			const attrs = cell?.attrs as CellAttrs;
			const copy = createNode(
				cell.type,
				{ ...attrs, rowspan: cell.attrs.rowspan - 1 },
				cell.content
			);
			const newPos = map.positionAt(row + 1, col, table);
			tr.insert(tr.mapping.slice(mapFrom).map(tableStart + newPos), copy);
			col += attrs.colspan - 1;
		}
	}
	return tr;
};

export const deleteRow: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	const $pos = selectionCell(state);

	if (dispatch) {
		const rect = selectedRect(state),
			tr = state.tr;
		if (rect.top == 0 && rect.bottom == rect.map.height) return false;
		for (let i = rect.bottom - 1; ; i--) {
			removeRow(tr, rect, i);
			if (i == rect.top) break;
			const table = rect.tableStart
				? tr.doc.nodeAt(rect.tableStart - 1)
				: tr.doc;
			if (!table) throw new RangeError('No table found');
			rect.table = table;
			rect.map = TableMap.get(table);
		}
		tr.setSelection(TextSelection.create(tr.doc, tr.mapping.map($pos.pos)));
		dispatch(tr);
	}
	return true;
};

export const deleteRowAtEnd = (view: EditorView, pos: number) => {
	const $pos = view.state.doc.resolve(pos);
	const table = $pos.nodeAfter!;
	const map = TableMap.get(table);
	if (map.height <= 1) return;
	const tr = removeRow(
		view.state.tr,
		{ map, table, tableStart: pos + 1 },
		map.height - 1
	);
	view.dispatch(tr);
};

const cellsOverlapRectangle = (
	{ width, height, map }: TableMap,
	rect: Rect
): boolean => {
	let indexTop = rect.top * width + rect.left,
		indexLeft = indexTop;

	let indexBottom = (rect.bottom - 1) * width + rect.left,
		indexRight = indexTop + (rect.right - rect.left - 1);

	for (let i = rect.top; i < rect.bottom; i++) {
		if (
			(rect.left > 0 && map[indexLeft] == map[indexLeft - 1]) ||
			(rect.right < width && map[indexRight] == map[indexRight + 1])
		)
			return true;
		indexLeft += width;
		indexRight += width;
	}
	for (let i = rect.left; i < rect.right; i++) {
		if (
			(rect.top > 0 && map[indexTop] == map[indexTop - width]) ||
			(rect.bottom < height && map[indexBottom] == map[indexBottom + width])
		)
			return true;

		indexTop++;
		indexBottom++;
	}
	return false;
};

const isEmpty = (cell: Node): Boolean => {
	const c = cell.content;
	return (
		c.childCount == 1 && c.child(0).isTextblock && c.child(0).childCount == 0
	);
};

export const mergeCells: Command = (state, dispatch) => {
	const sel = state.selection;
	if (
		!(sel instanceof CellSelection) ||
		sel.$anchorCell.pos == sel.$headCell.pos
	)
		return false;

	const rect = selectedRect(state),
		{ map, table, tableStart } = rect;
	if (cellsOverlapRectangle(map, rect)) return false;

	if (dispatch) {
		const tr = state.tr;
		const seen: Record<number, boolean> = {};
		let content = Fragment.empty;
		let mergedPos: number | undefined;
		let mergedCell: Node | undefined;
		let colwidth: number[] = [];

		if (rect.right === map.width && rect.left > 0) {
			for (let row = rect.top + 1; row < rect.bottom; row++) {
				const pos = map.positionAt(row, rect.left - 1, table);
				tr.setNodeAttribute(pos + tableStart, 'class', 'last-in-cell');
			}
		}

		for (let col = rect.left; col < rect.right; col++) {
			const cellPos = map.map[rect.top * map.width + col];
			const cell = table.nodeAt(cellPos);
			if (!cell) continue;
			colwidth = colwidth.concat(cell.attrs.colwidth);
		}
		for (let row = rect.top; row < rect.bottom; row++) {
			for (let col = rect.left; col < rect.right; col++) {
				const cellPos = map.map[row * map.width + col];
				const cell = rect.table.nodeAt(cellPos);
				if (seen[cellPos] || !cell) continue;
				seen[cellPos] = true;

				if (mergedPos == null) {
					mergedPos = cellPos;
					mergedCell = cell;
				} else {
					if (!isEmpty(cell)) content = content.append(cell.content);
					const mapped = tr.mapping.map(cellPos + tableStart);
					tr.delete(mapped, mapped + cell.nodeSize);
				}
			}
		}
		if (mergedPos == null || mergedCell == null) return true;
		tr.setNodeMarkup(mergedPos + tableStart, null, {
			...addColspan(
				{ ...(mergedCell.attrs as CellAttrs), colwidth },
				mergedCell.attrs.colspan,
				rect.right - rect.left - mergedCell.attrs.colspan
			),
			rowspan: rect.bottom - rect.top
		});
		if (content.size) {
			const end = mergedPos + 1 + mergedCell.content.size;
			const start = isEmpty(mergedCell) ? mergedPos + 1 : end;
			tr.replaceWith(start + tableStart, end + tableStart, content);
		}
		tr.setSelection(new CellSelection(tr.doc.resolve(mergedPos + tableStart)));
		dispatch(tr);
	}

	return true;
};

export const splitCell: Command = (state, dispatch) => {
	const nodeTypes = tableNodeTypes(state.schema);
	return splitCellWithType(({ node }) => {
		return nodeTypes[node.type.spec.tableRole as TableRole];
	})(state, dispatch);
};

function splitCellWithType(
	getCellType: (e: { node: Node; row: number; col: number }) => NodeType
): Command {
	return (state, dispatch) => {
		var _a;
		const sel = state.selection;
		let cellNode;
		let cellPos;
		const ctx = { lastCell: -1, getCellType, tr: state.tr };
		const fn = splitCellOneWithType(ctx);
		const rect1 = selectedRect(state),
			{ table, tableStart, map, ...rect } = rect1;
		if (!(sel instanceof CellSelection)) {
			cellNode = cellWrapping(sel.$from);
			if (!cellNode) return false;
			cellPos = (_a = cellAround(sel.$from)) == null ? void 0 : _a.pos;
			fn(cellNode, cellPos, rect1);
		} else {
			// if (sel.$anchorCell.pos != sel.$headCell.pos) return false;
			// cellNode = sel.$anchorCell.nodeAfter;
			// cellPos = sel.$anchorCell.pos;
			const params = [];
			const seen: Record<number, boolean> = {};
			for (let row = rect.top; row < rect.bottom; row++) {
				for (let col = rect.left; col < rect.right; col++) {
					const cellPos = map.map[row * map.width + col]; // 获取单元格位置
					const cell = table.nodeAt(cellPos);
					if (!cell || seen[cellPos]) continue;
					seen[cellPos] = true;
					const { colspan = 1, rowspan = 1 } = cell.attrs;

					if (colspan > 1 || rowspan > 1) {
						params.push([
							cell,
							cellPos + tableStart,
							{
								top: row,
								bottom: row + rowspan,
								left: col,
								right: col + colspan,
								table,
								map,
								tableStart
							}
						] as const);
						col += colspan - 1;
					}
				}
			}

			params.forEach(([node, pos, rect]) => {
				fn(node, ctx.tr.mapping.map(pos), rect);
			});
		}

		if (dispatch) {
			let { tr, lastCell } = ctx;
			if (sel instanceof CellSelection)
				tr.setSelection(
					new CellSelection(
						tr.doc.resolve(tr.mapping.map(sel.$anchorCell.pos)),
						lastCell ? tr.doc.resolve(lastCell) : void 0
					)
				);
			dispatch(tr);
		}
		return true;
	};
}

export const setCellAttrs =
	(name: string, value: unknown): Command =>
	(state, dispatch) => {
		if (!isInTable(state)) return false;
		const $cell = selectionCell(state);
		if ($cell.nodeAfter!.attrs[name] === value) return false;
		if (dispatch) {
			const tr = state.tr;
			if (state.selection instanceof CellSelection)
				state.selection.forEachCell((node, pos) => {
					if (node.attrs[name] !== value)
						tr.setNodeMarkup(pos, null, {
							...node.attrs,
							[name]: value
						});
				});
			else
				tr.setNodeMarkup($cell.pos, null, {
					...$cell.nodeAfter!.attrs,
					[name]: value
				});
			dispatch(tr);
		}

		return true;
	};

function isHeaderEnabledByType(
	type: 'row' | 'column',
	rect: TableRect,
	types: Record<string, NodeType>
): boolean {
	// Get cell positions for first row or first column
	const cellPositions = rect.map.cellsInRect({
		left: 0,
		top: 0,
		right: type == 'row' ? rect.map.width : 1,
		bottom: type == 'column' ? rect.map.height : 1
	});

	for (let i = 0; i < cellPositions.length; i++) {
		const cell = rect.table.nodeAt(cellPositions[i]);
		if (cell && cell.type !== types.headerCell) {
			return false;
		}
	}

	return true;
}

export type ToggleHeaderType = 'column' | 'row' | 'cell';

export function toggleHeader(
	type: ToggleHeaderType,
	options?: { useDeprecatedLogic: boolean } | undefined
): Command {
	options = options || { useDeprecatedLogic: false };

	// if (options.useDeprecatedLogic) return deprecated_toggleHeader(type);

	return function (state, dispatch) {
		if (!isInTable(state)) return false;
		if (dispatch) {
			const types = tableNodeTypes(state.schema);
			const rect = selectedRect(state),
				tr = state.tr;

			const isHeaderRowEnabled = isHeaderEnabledByType('row', rect, types);
			const isHeaderColumnEnabled = isHeaderEnabledByType(
				'column',
				rect,
				types
			);

			const isHeaderEnabled =
				type === 'column'
					? isHeaderRowEnabled
					: type === 'row'
						? isHeaderColumnEnabled
						: false;

			const selectionStartsAt = isHeaderEnabled ? 1 : 0;

			const cellsRect =
				type == 'column'
					? {
							left: 0,
							top: selectionStartsAt,
							right: 1,
							bottom: rect.map.height
						}
					: type == 'row'
						? {
								left: selectionStartsAt,
								top: 0,
								right: rect.map.width,
								bottom: 1
							}
						: rect;

			const newType =
				type == 'column'
					? isHeaderColumnEnabled
						? types.cell
						: types.headerCell
					: type == 'row'
						? isHeaderRowEnabled
							? types.cell
							: types.headerCell
						: types.cell;

			rect.map.cellsInRect(cellsRect).forEach((relativeCellPos) => {
				const cellPos = relativeCellPos + rect.tableStart;
				const cell = tr.doc.nodeAt(cellPos);

				if (cell) {
					tr.setNodeMarkup(cellPos, newType, cell.attrs);
				}
			});

			dispatch(tr);
		}
		return true;
	};
}

function findNextCell($cell: ResolvedPos, dir: Direction): number | null {
	if (dir < 0) {
		const before = $cell.nodeBefore;
		if (before) return $cell.pos - before.nodeSize;
		for (
			let row = $cell.index(-1) - 1, rowEnd = $cell.before();
			row >= 0;
			row--
		) {
			const rowNode = $cell.node(-1).child(row);
			const lastChild = rowNode.lastChild;
			if (lastChild) return rowEnd - 1 - lastChild.nodeSize;
			return (rowEnd -= rowNode.nodeSize);
		}
	} else {
		if ($cell.index() < $cell.parent.childCount - 1)
			return $cell.pos + $cell.nodeAfter!.nodeSize;
		const table = $cell.node(-1);
		for (
			let row = $cell.indexAfter(-1), rowStart = $cell.after();
			row < table.childCount;
			row++
		) {
			const rowNode = table.child(row);
			if (rowNode.childCount) return rowStart + 1;
			rowStart += rowNode.nodeSize;
		}
	}

	return null;
}

export const goToNextCell =
	(direction: Direction): Command =>
	(state, dispatch) => {
		if (!isInTable(state)) return false;
		const cell = findNextCell(selectionCell(state), direction);
		if (cell == null) return false;
		if (dispatch) {
			const $cell = state.doc.resolve(cell);
			dispatch(
				state.tr
					.setSelection(TextSelection.between($cell, moveCellForward($cell)))
					.scrollIntoView()
			);
		}
		return true;
	};

export const deleteTable: Command = (state, dispatch) => {
	const $pos = state.selection.$anchor;
	for (let d = $pos.depth; d > 0; d--) {
		const node = $pos.node(d);
		if (node.type.spec.tableRole == 'table') {
			if (dispatch) {
				dispatch(
					state.tr.delete($pos.before(d), $pos.after(d)).scrollIntoView()
				);
				return true;
			}
		}
	}
	return false;
};

export const attrsChange =
	(
		key: 'textAlign' | 'color' | 'backgroundColor',
		val: Align | string
	): Command =>
	(state, dispatch) => {
		const { map, tableStart, ...rect } = selectedRect(state);
		if (dispatch) {
			const tr = state.tr;
			map.cellsInRect(rect).forEach((pos) => {
				tr.setNodeAttribute(pos + tableStart, key, val);
			});
			dispatch(tr);
		}
		return false;
	};

export const clearContent: Command = (state, dispatch) => {
	if (!isInTable(state)) return false;
	const { map, table, tableStart, ...rect } = selectedRect(state);
	const { tr, selection } = state;
	let cellPos;
	map.cellsInRect(rect).forEach((pos) => {
		const cellNode = table.nodeAt(pos);
		if (!cellNode) return;
		cellPos = pos;
		const emptyCell = createNodeAndFill(cellNode.type);
		if (emptyCell) {
			tr.replaceWith(
				tr.mapping.map(tableStart + pos + 1),
				tr.mapping.map(tableStart + pos + cellNode.nodeSize - 1),
				emptyCell.content
			);
		}
	});
	if (selection instanceof TextSelection && cellPos)
		tr.setSelection(TextSelection.create(tr.doc, cellPos));

	if (dispatch) {
		dispatch(tr);
		return true;
	}
	return false;
};
