import { closeFloatBar, showFloatBar } from '../components/toolBar/FloatBar';
import { splitTimeline } from '../components/timeline';
import { joinBackward } from './utils';

const splitListItem = (itemTypes: NodeType[], itemAttrs?: Attrs): Command => {
	return (state, dispatch) => {
		let { $from, $to, node } = state.selection as NodeSelection;
		if ((node && node.isBlock) || $from.depth < 2 || !$from.sameParent($to))
			return false;
		let grandParent = $from.node(-1);
		const contentType = grandParent.contentMatchAt(0).defaultType;
		if (!itemTypes.includes(grandParent.type)) return false;

		const liCount = $from.node(-2).childCount;
		if (
			$from.parent.content.size == 0 &&
			$from.node(-1).childCount == $from.indexAfter(-1)
		) {
			if (
				$from.depth == 3 ||
				!itemTypes.includes($from.node(-3).type) ||
				$from.index(-2) != liCount - 1
			)
				return false;
			if (dispatch) {
				let wrap = Fragment.empty;
				let depthBefore = $from.index(-1) ? 1 : $from.index(-2) ? 2 : 3;
				console.log(depthBefore, $from, $from.index(-1), $from.index(-2));

				// Build a fragment containing empty versions of the structure
				// from the outer list item to the parent node of the cursor
				for (let d = $from.depth - depthBefore; d >= $from.depth - 3; d--)
					wrap = Fragment.from($from.node(d).copy(wrap));
				console.log(wrap, $from.node(4), $from.node(3));

				let depthAfter =
					$from.indexAfter(-1) < $from.node(-2).childCount
						? 1
						: $from.indexAfter(-2) < $from.node(-3).childCount
							? 2
							: 3;
				// Add a second list item with an empty default start node
				// wrap = wrap.append(Fragment.from(createNodeAndFill(itemTypes[0])));
				wrap = wrap.append(
					Fragment.from(
						createNode(grandParent.type, null, createNode(contentType!))
					)
				);

				let start = $from.before($from.depth - (depthBefore - 1));
				const s = new Slice(wrap, 4 - depthBefore, 0);
				let tr = state.tr.replace(start, $from.after(-depthAfter), s);
				let sel = -1;
				tr.doc.nodesBetween(start, tr.doc.content.size, (node, pos) => {
					if (sel > -1) return false;
					if (node.isTextblock && node.content.size == 0) sel = pos + 1;
				});
				if (sel > -1) tr.setSelection(Selection.near(tr.doc.resolve(sel)));
				dispatch(tr.scrollIntoView());
			}
			return true;
		}
		let nextType = $to.pos == $from.end() ? contentType : null;
		let tr = state.tr.delete($from.pos, $to.pos);
		let types = nextType
			? [
					// itemAttrs ? { type: itemTypes[0], attrs: itemAttrs } : null,
					{ type: grandParent.type },
					{ type: nextType }
				]
			: undefined;
		if (!canSplit(tr.doc, $from.pos, 2, types)) return false;
		if (dispatch) dispatch(tr.split($from.pos, 2, types).scrollIntoView());
		return true;
	};
};

function findNextVisiblePos(doc: Node, pos: number) {
	let currentPos = pos;
	while (currentPos < doc.content.size) {
		const node = doc.nodeAt(currentPos);
		if (!node) break;
		if (!node.attrs.hidden) return currentPos;
		currentPos += node.nodeSize;
	}
	return currentPos;
}

const headingEnter: Command = (state, dispatch) => {
	const { $from, $to } = state.selection;
	if (!$from.sameParent($to) || $from.parent.type !== schema.nodes.heading)
		return false;
	const pos = $from.after();
	const node = $from.parent;
	if (dispatch && node.attrs.fold) {
		const position = findNextVisiblePos(state.doc, pos);
		let tr = state.tr.insert(
			position,
			createNode(schema.nodes.heading, { level: node.attrs.level })
		);
		tr = tr.setSelection(TextSelection.create(tr.doc, position + 1));
		dispatch(tr);

		return true;
	}
	return false;
};

let timer: ReturnType<typeof setTimeout>;

const openFloatBar: Command = (state, dispatch, view) => {
	if (!view) return false;

	if (timer) clearTimeout(timer);

	timer = setTimeout(() => {
		const {
			state: { selection }
		} = view;
		if (selection.empty) {
			closeFloatBar();
		} else {
			showFloatBar(view);
		}
	}, 500);

	return false;
};

const backspace = chainCommands(
	deleteSelection,
	joinBackward,
	selectNodeBackward
);

[
	'Backspace',
	'Mod-Backspace',
	'Shift-Backspace',
	'Ctrl-h',
	'Alt-Backspace'
].forEach((key) => {
	baseKeymap[key] = backspace;
});

export const getMyKeyMap = () => {
	const myKeymap: { [key: string]: Command } = {
		...baseKeymap,
		Enter: chainCommands(
			headingEnter,
			splitListItem([schema.nodes.list_item, schema.nodes.taskItem]),
			splitTimeline,
			newlineInCode,
			createParagraphNear,
			liftEmptyBlock,
			splitBlock
		),
		'Mod-z': undo,
		'Mod-y': redo,
		Tab: (state: EditorState, dispatch?: EditorView['dispatch']) => {
			console.log('tab');

			const { $from, $to } = state.selection;
			if (
				!$from.sameParent($to) ||
				$from.parent.type !== schema.nodes.codeBlock
			)
				return false;
			if (dispatch) {
				dispatch(state.tr.insertText('\t'));
				return true;
			}
			return false;
		},
		'Ctrl-Shift-L': createTaskList,
		'Shift-ArrowLeft': openFloatBar,
		'Shift-ArrowRight': openFloatBar,
		'Shift-ArrowUp': openFloatBar,
		'Shift-ArrowDown': openFloatBar
	};
	return myKeymap;
};
